.ui-list--check li::before {
  content: "✓";
  color: var(--studio-green);
  margin-right: 7px;
  font-size: 0.8em;
}

.ui-divider {
  border: none;
  border-top: 1px solid var(--studio-border);
  margin: 2px 0;
  width: 100%;
}

/* Actions */
.ui-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.ui-action {
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 7px 12px;
  font-size: 0.82rem;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease,
    transform 0.1s ease;
}

.ui-action--primary {
  background: var(--studio-indigo-strong);
  border-color: rgba(255, 255, 255, 0.08);
  color: #fff;
}

.ui-action--primary:hover {
  background: #7c7ff5;
}

.ui-action--ghost {
  background: transparent;
  border-color: var(--studio-border);
  color: #cbd5e1;
}

.ui-action--ghost:hover {
  border-color: rgba(129, 140, 248, 0.45);
  color: var(--studio-text);
}

.ui-action:active {
  transform: translateY(1px);
}

.ui-action:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

/* Tables */
.ui-table-wrap {
  overflow-x: auto;
}

.ui-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.86rem;
}

.ui-table th {
  padding: 0 0 6px;
  border-bottom: 1px solid var(--studio-border);
  text-align: left;
  font-size: 0.66rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--studio-muted);
}

.ui-table td {
  padding: 9px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.04);
  vertical-align: top;
}

.ui-table tr:last-child td {
  border-bottom: none;
}

.ui-table td:first-child {
  padding-right: 12px;
}

.ui-table td:last-child {
  text-align: right;
  white-space: nowrap;
}

.ui-table .ui-card__id {
  display: block;
}

.ui-table__statement {
  display: block;
  margin-top: 3px;
  line-height: 1.4;
  color: #cbd5e1;
}

.ui-table__row--urgent .ui-card__id {
  color: var(--studio-amber);
}

/* Impact simulation */
.ui-bet {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 9px 12px;
  border-radius: 8px;
  border: 1px solid rgba(129, 140, 248, 0.2);
  background: rgba(129, 140, 248, 0.07);
}

.ui-bet__label {
  font-size: 0.64rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--studio-indigo);
  white-space: nowrap;
}

.ui-bet__value {
  font-size: 0.88rem;
  color: #e2e8f0;
}

.ui-phase {
  padding: 12px;
  border-radius: 10px;
  border: 1px solid;
  min-width: 0;
}

.ui-phase.ui-tone--critical {
  background: rgba(248, 113, 113, 0.06);
  border-color: rgba(248, 113, 113, 0.22);
}

.ui-phase.ui-tone--positive {
  background: rgba(52, 211, 153, 0.06);
  border-color: rgba(52, 211, 153, 0.22);
}

.ui-phase__label {
  margin-bottom: 7px;
  font-size: 0.64rem;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--studio-muted);
}

.ui-phase__items {
  margin: 0;
  padding-left: 16px;
  display: flex;
  flex-direction: column;
  gap: 5px;
  font-size: 0.84rem;
  color: #cbd5e1;
}

/* Evidence */
.ui-quote {
  margin: 0;
  padding-left: 12px;
  border-left: 2px solid rgba(129, 140, 248, 0.5);
  font-size: 0.95rem;
  font-style: italic;
  line-height: 1.55;
  color: #e2e8f0;
}

/* Job map */
.ui-jobmap {
  list-style: none;
  margin: 0;
  padding: 0;
}

.ui-jobmap__step {
  display: flex;
  gap: 10px;
  padding: 8px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.04);
}

.ui-jobmap__step:last-child {
  border-bottom: none;
}

.ui-jobmap__index {
  flex: none;
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  border-radius: 6px;
  background: rgba(129, 140, 248, 0.14);
  color: var(--studio-indigo);
  font-size: 0.7rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.ui-jobmap__body {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ui-jobmap__name {
  font-size: 0.88rem;
}

.ui-jobmap__stage {
  font-size: 0.64rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--studio-muted);
}

.ui-jobmap__note {
  font-size: 0.78rem;
  color: var(--studio-muted);
}

/* Decision record */
.ui-fields {
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.ui-field {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ui-field dt {
  font-size: 0.64rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--studio-muted);
}

.ui-field dd {
  margin: 0;
  font-size: 0.88rem;
  color: #e2e8f0;
}

@media (max-width: 640px) {
  .ui-grid--2,
  .ui-grid--3 {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (prefers-reduced-motion: reduce) {
  .ui-surface {
    animation: none;
  }

  .ui-meter__fill {
    transition: none;
  }
}

/* Markdown inside a surface. Cards are dense; paragraphs should hug. */
.ui-card .md-paragraph,
.ui-callout__body .md-paragraph,
.ui-card__evidence .md-paragraph,
.ui-quote .md-paragraph {
  margin: 0 0 6px;
}

.ui-card .md-paragraph:last-child,
.ui-callout__body .md-paragraph:last-child,
.ui-card__evidence .md-paragraph:last-child,
.ui-quote .md-paragraph:last-child {
  margin-bottom: 0;
}

.ui-card .md-list,
.ui-callout__body .md-list {
  margin: 4px 0 0;
}

/* A surface sits in the prose, not outside it. */
.message__body > .ui-surface {
  margin: 12px 0;
}

/* ------------------------------------------------------------------ */
/* Discrete Changelog Modal (Steve Jobs Quality)                     */
/* ------------------------------------------------------------------ */
.pill-changelog {
  background: rgba(129, 140, 248, 0.18);
  color: #a5b4fc;
  border: 1px solid rgba(129, 140, 248, 0.4);
  cursor: pointer;
  transition: all 0.2s ease;
}

.pill-changelog:hover {
  background: rgba(129, 140, 248, 0.3);
  border-color: #818cf8;
  color: #ffffff;
  box-shadow: 0 0 12px rgba(129, 140, 248, 0.25);
}

.changelog-overlay {
  position: fixed;
  inset: 0;
  z-index: 2000;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(11, 13, 19, 0.75);
  backdrop-filter: blur(12px);
  padding: 20px;
}

.changelog-modal {
  width: 100%;
  max-width: 680px;
  max-height: 85vh;
  display: flex;
  flex-direction: column;
  background: linear-gradient(145deg, rgba(26, 32, 48, 0.95), rgba(15, 20, 32, 0.98));
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 16px;
  box-shadow: 0 24px 48px rgba(0, 0, 0, 0.6), 0 0 1px rgba(255, 255, 255, 0.2) inset;
  overflow: hidden;
}

.changelog-modal__header {
  padding: 20px 24px 16px;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  border-bottom: 1px solid var(--studio-border);
}

.changelog-modal__badge {
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  color: #818cf8;
  margin-bottom: 4px;
}

.changelog-modal__title {
  margin: 0;
  font-size: 1.35rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--studio-text);
}

.changelog-modal__close {
  background: transparent;
  border: none;
  color: var(--studio-muted);
  font-size: 1.1rem;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 6px;
  transition: color 0.15s ease, background 0.15s ease;
}

.changelog-modal__close:hover {
  color: var(--studio-text);
  background: rgba(255, 255, 255, 0.08);
}

.changelog-modal__body {
  padding: 24px;
  overflow-y: auto;
  flex: 1;
}

.changelog-timeline {
  display: flex;
  flex-direction: column;
  gap: 28px;
}

.changelog-release {
  display: grid;
  grid-template-columns: 100px 1fr;
  gap: 16px;
  position: relative;
}

@media (max-width: 600px) {
  .changelog-release {
    grid-template-columns: 1fr;
    gap: 8px;
  }
}

.changelog-release__meta {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.changelog-release__version {
  font-weight: 700;
  font-size: 1rem;
  color: #818cf8;
}

.changelog-release__date {
  font-size: 0.78rem;
  color: var(--studio-muted);
}

.changelog-release__content {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.changelog-category__title {
  font-size: 0.82rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: #a5b4fc;
  margin: 0 0 6px;
}

.changelog-category__list {
  margin: 0;
  padding-left: 18px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.changelog-category__item {
  font-size: 0.88rem;
  line-height: 1.45;
  color: #cbd5e1;
}

.changelog-modal__footer {
  padding: 16px 24px;
  border-top: 1px solid var(--studio-border);
  background: rgba(0, 0, 0, 0.2);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.changelog-modal__quote {
  font-size: 0.78rem;
  font-style: italic;
  color: var(--studio-muted);
}

.changelog-modal__loading,
.changelog-modal__error {
  padding: 24px 0;
}

/* ================================================================== */
/* PR #61 micro-interactions (reconciled onto main)                  */
/* ================================================================== */
:root {
  --ease-apple-spring: cubic-bezier(0.175, 0.885, 0.32, 1.22);
  --ease-apple-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-tactile: cubic-bezier(0.2, 0.8, 0.2, 1);
}

/* 1. Glassmorphic Backdrop Blur & Vibrancy on elevated panels */
.bar,
.outcome-card,
.settings-drawer,
.toast,
.changelog-modal {
  backdrop-filter: blur(12px) saturate(160%);
  -webkit-backdrop-filter: blur(12px) saturate(160%);
}

/* 2. Apple-style range slider dynamics */
input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  background: rgba(255, 255, 255, 0.1);
  height: 6px;
  border-radius: 3px;
  outline: none;
  margin: 10px 0;
}

input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--accent);
  cursor: pointer;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.4);
  transition: transform 0.15s var(--ease-apple-spring), background 0.15s var(--ease-apple-out);
}

input[type="range"]::-webkit-slider-thumb:hover {
  transform: scale(1.25);
  background: var(--accent-strong);
}

input[type="range"]::-webkit-slider-thumb:active {
  transform: scale(1.1);
  box-shadow: 0 0 0 4px rgba(99, 149, 245, 0.3);
}

/* 3. Settings Accordion / Drawer smooth expansion */
details {
  transition: all 0.25s var(--ease-apple-out);
}

details summary {
  cursor: pointer;
  user-select: none;
  font-weight: 500;
  transition: color 0.15s ease;
}

details summary:hover {
  color: var(--accent);
}

details[open] summary {
  margin-bottom: 8px;
}

/* 6. Live status pill dot pulse indicator */
.studio-pill::before,
.status-dot::before {
  content: "";
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}

@keyframes pill-dot-pulse {
  0%, 100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.4;
    transform: scale(0.75);
  }
}

.pill-green::before,
.pill-amber::before,
.pill-blue::before {
  animation: pill-dot-pulse 2s ease-in-out infinite;
}

/* 16. Evidence stream signal pulse */
@keyframes evidencePulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.6; }
}

/* 18. Pulsing fire glow on underserved cards */
@keyframes pulse-amber-glow {
  0%,
  100% {
    box-shadow: 0 0 12px rgba(245, 158, 11, 0.25), inset 0 0 6px rgba(245, 158, 11, 0.08);
    border-left-color: #f59e0b;
  }
  50% {
    box-shadow: 0 0 24px rgba(245, 158, 11, 0.5), inset 0 0 12px rgba(245, 158, 11, 0.15);
    border-left-color: #fbbf24;
  }
}

/* 9. Chat bubble entrance spring */
@keyframes chatBubblePopIn {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.95);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* 10. Agent thinking wave pulse */
@keyframes thinkingPulse {
  0%, 100% {
    opacity: 0.4;
    transform: scale(0.98);
  }
  50% {
    opacity: 1;
    transform: scale(1.02);
  }
}

/* 11. Toast stack pop & elastic slide-in */
@keyframes toastSlideIn {
  0% {
    opacity: 0;
    transform: translateX(40px) scale(0.9);
  }
  70% {
    transform: translateX(-4px) scale(1.02);
  }
  100% {
    opacity: 1;
    transform: translateX(0) scale(1);
  }
}

.toast {
  animation: toastSlideIn 0.35s var(--ease-apple-spring) forwards;
}

/* 17. Quick prompt button shimmer / pulse glow */
.chat-quick-pills button {
  position: relative;
  overflow: hidden;
}

.chat-quick-pills button::after {
  content: "";
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: linear-gradient(
    60deg,
    transparent,
    rgba(255, 255, 255, 0.08),
    transparent
  );
  transform: rotate(30deg) translateX(-100%);
  transition: transform 0.6s ease;
}

.chat-quick-pills button:hover::after {
  transform: rotate(30deg) translateX(100%);
}

/* 20. Accessibility & motion preference respect */
@media (prefers-reduced-motion: reduce) {
  *,
  ::before,
  ::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
/* ------------------------------------------------------------------ */
/* One room: the conversation never leaves the stage                  */
/* ------------------------------------------------------------------ */
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.brand--home {
  padding: 4px 8px 4px 2px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: background 0.14s ease;
}

.brand--home:hover {
  background: var(--surface-hover);
}

.brand--home:hover .brand__wordmark {
  color: var(--text);
}

.brand__wordmark {
  color: var(--muted);
  font-size: 0.88rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  white-space: nowrap;
  transition: color 0.14s ease;
}

.brand__mark {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  flex: none;
  border-radius: 9px;
  color: #d6d7ff;
  background: linear-gradient(140deg, rgba(99, 102, 241, 0.55), rgba(139, 92, 246, 0.25));
  border: 1px solid rgba(139, 140, 248, 0.35);
}

.icon-button {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: 32px;
  height: 32px;
  flex: none;
  border: 1px solid transparent;
  border-radius: 9px;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  transition:
    background 0.14s ease,
    color 0.14s ease;
}

.icon-button:hover {
  background: var(--surface-hover);
  color: var(--text);
}

.status-dot {
  width: 7px;
  height: 7px;
  flex: none;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 0 3px rgba(74, 222, 128, 0.12);
}

.status-dot.is-warn {
  background: var(--amber);
  box-shadow: 0 0 0 3px rgba(240, 179, 74, 0.14);
}

.status-dot.is-unknown {
  background: #5b616c;
  box-shadow: none;
}

.bar__bell {
  position: relative;
}

.stage__split {
  display: flex;
  flex: 1;
  min-width: 0;
  min-height: 0;
}

.stage__thread {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
  min-height: 0;
}

/* ------------------------------------------------------------------ */
/* Rail: what the thread has made, above the thread                   */
/* ------------------------------------------------------------------ */
.rail {
  flex: none;
  padding: 0 22px;
}

.rail__list {
  display: flex;
  align-items: center;
  gap: 2px;
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  padding: 0 0 6px;
  list-style: none;
  overflow-x: auto;
  scrollbar-width: none;
  animation: fade-in 0.24s ease;
}

.rail__list::-webkit-scrollbar {
  display: none;
}

.rail__chip {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 5px 9px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: var(--faint);
  font-size: 0.76rem;
  white-space: nowrap;
  cursor: pointer;
  transition:
    color 0.14s ease,
    background 0.14s ease,
    border-color 0.14s ease;
}

.rail__chip:hover {
  color: var(--text);
  background: var(--surface);
}

.rail__chip.is-open {
  color: var(--text);
  background: var(--surface);
  border-color: var(--line);
}

.rail__icon {
  display: inline-flex;
  opacity: 0.8;
}

.rail__count {
  color: var(--faint);
  font-variant-numeric: tabular-nums;
}

.rail__chip.is-open .rail__count {
  color: var(--muted);
}

/* ------------------------------------------------------------------ */
/* Lens: a view docks beside the conversation, never over it          */
/* ------------------------------------------------------------------ */
.lens {
  display: flex;
  flex-direction: column;
  flex: none;
  width: min(520px, 44vw);
  min-width: 360px;
  min-height: 0;
  border-left: 1px solid var(--line);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.022), rgba(255, 255, 255, 0.006)),
    var(--bg-raised);
  animation: lens-in 0.22s cubic-bezier(0.16, 1, 0.3, 1);
}

.lens__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  flex: none;
  padding: 16px 18px 14px;
  border-bottom: 1px solid var(--line);
}

.lens__heading {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  min-width: 0;
}

.lens__icon {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  flex: none;
  border-radius: 9px;
  background: var(--surface);
  color: var(--muted);
}

.lens__title {
  margin: 0;
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}

.lens__blurb {
  margin: 3px 0 0;
  max-width: 42ch;
  color: var(--faint);
  font-size: 0.755rem;
  line-height: 1.45;
}

.lens__body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 22px 20px 32px;
  scrollbar-gutter: stable;
}

.lens__content {
  width: 100%;
}

.lens__foot {
  flex: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px 18px 16px;
  border-top: 1px solid var(--line);
  background: linear-gradient(to top, rgba(10, 11, 14, 0.9), transparent);
}

.lens__note {
  margin: 0;
  color: var(--faint);
  font-size: 0.72rem;
  text-align: center;
}

@keyframes lens-in {
  from {
    opacity: 0;
    transform: translateX(12px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.catchup-title {
  margin: 0;
  font-weight: 600;
  letter-spacing: -0.01em;
}

metadata.output:
...

olor: var(--faint);
}

.card__edit {
