* {

display.text:
:root {
  color-scheme: dark;
  --bg: #0a0b0e;
  --bg-raised: #0e1014;
  --text: #f1f2f4;
  --muted: #a2a7b3;
  --faint: #71767f;
  --accent: #8b8cf8;
  --accent-strong: #6366f1;
  --green: #4ade80;
  --amber: #f0b34a;
  --line: rgba(255, 255, 255, 0.07);
  --line-strong: rgba(255, 255, 255, 0.14);
  --surface: rgba(255, 255, 255, 0.03);
  --surface-hover: rgba(255, 255, 255, 0.06);
  --font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  -webkit-font-smoothing: antialiased;
}

button,
input,
select,
textarea {
  font-family: inherit;
  color: inherit;
}

button {
  -webkit-tap-highlight-color: transparent;
}

a {
  color: #a5b4fc;
  text-decoration: underline;
  text-underline-offset: 2px;
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ------------------------------------------------------------------ */
/* Shell                                                              */
/* ------------------------------------------------------------------ */
.studio-app {
  height: 100dvh;
  display: flex;
  flex-direction: column;
  background: var(--bg);
  overflow: hidden;
}

.scrim {
  position: fixed;
  inset: 0;
  z-index: 50;
  border: 0;
  padding: 0;
  background: rgba(0, 0, 0, 0.55);
  backdrop-filter: blur(2px);
  cursor: default;
}

/* ------------------------------------------------------------------ */
/* Stage                                                              */
/* ------------------------------------------------------------------ */
.stage {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
  min-height: 0;
  background:
    radial-gradient(760px 420px at 50% 108%, rgba(99, 102, 241, 0.09), transparent 72%),
    radial-gradient(900px 520px at 68% -12%, rgba(99, 102, 241, 0.08), transparent 68%);
}

.bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex: none;
  height: 56px;
  padding: 0 18px;
}

.bar__left,
.bar__right {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.bar__brand {
  padding: 4px 8px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  font: inherit;
  font-size: 0.8rem;
  color: var(--muted);
  white-space: nowrap;
  cursor: pointer;
}

.bar__brand:hover {
  background: var(--surface-hover);
  color: var(--text);
}

.bar__health {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 5px 11px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: transparent;
  color: var(--faint);
  font-size: 0.72rem;
  cursor: pointer;
}

.bar__health:hover {
  color: var(--muted);
  border-color: var(--line-strong);
}

/* ------------------------------------------------------------------ */
/* Conversation                                                       */
/* ------------------------------------------------------------------ */
.chat {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
  min-height: 0;
}

.chat__welcome {
  display: flex;
  justify-content: center;
  flex: 1;
  min-height: 0;
  padding: 12px 22px 56px;
  overflow-y: auto;
}

.chat__welcome-inner {
  display: flex;
  flex-direction: column;
  gap: 28px;
  width: 100%;
  max-width: 720px;
  /* auto block margins centre when there is room and scroll when there isn't */
  margin-block: auto;
}

/* Sits the hero + composer a little above the bottom edge on tall screens. */
.chat--empty .chat__welcome {
  padding-bottom: max(56px, 14vh);
}

.chat__scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 6px 22px 20px;
  scrollbar-gutter: stable;
}

.chat__thread {
  max-width: 720px;
  margin: 0 auto;
}

.chat__dock {
  flex: none;
  padding: 6px 22px 16px;
  background: linear-gradient(to top, var(--bg) 60%, transparent);
}

.chat__dock > * {
  max-width: 720px;
  margin: 0 auto;
}

/* Hero */
.hero {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  text-align: center;
}

.hero__eyebrow {
  margin: 0;
  font-size: 0.67rem;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--faint);
}

.hero__line {
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0;
  min-height: 2.34em;
  max-width: 24ch;
  font-size: clamp(1.55rem, 3.4vw, 2.25rem);
  font-weight: 600;
  line-height: 1.17;
  letter-spacing: -0.03em;
  animation: hero-in 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

.hero__sub {
  margin: 0;
  max-width: 46ch;
  color: var(--muted);
  font-size: 0.88rem;
  line-height: 1.55;
}

.hero__pills {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 7px;
  margin-top: 2px;
}

.suggestion {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6px 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.025);
  color: var(--muted);
  font-size: 0.775rem;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, transform 0.15s ease,
    border-color 0.15s ease;
}

.suggestion:hover:not(:disabled) {
  background: var(--surface-hover);
  border-color: var(--line-strong);
  color: var(--text);
  transform: translateY(-1px);
}

.suggestion:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Composer */
.composer {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
}

/* Slash-command palette */
.palette {
  position: absolute;
  bottom: calc(100% + 10px);
  left: 0;
  right: 0;
  z-index: 20;
  max-height: min(320px, 46vh);
  overflow-y: auto;
  padding: 6px;
  border: 1px solid var(--line-strong);
  border-radius: 14px;
  background: var(--bg-raised);
  box-shadow: 0 24px 50px rgba(0, 0, 0, 0.42);
  animation: fade-in 0.12s ease;
}

.palette__item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  width: 100%;
  padding: 8px 10px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: var(--text);
  text-align: left;
  cursor: pointer;
}

.palette__item.is-active {
  background: var(--surface-hover);
}

.palette__name {
  flex: none;
  width: 84px;
  padding-top: 1px;
  color: #c7c8ff;
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: 0.76rem;
}

.palette__text {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}

.palette__label {
  font-size: 0.8rem;
  font-weight: 600;
}

.palette__description {
  color: var(--faint);
  font-size: 0.72rem;
  line-height: 1.4;
}

.palette__empty {
  margin: 0;
  padding: 10px 12px;
  color: var(--faint);
  font-size: 0.78rem;
}

.composer__shell {
  display: flex;
  align-items: flex-end;
  gap: 10px;
  padding: 8px 9px 8px 16px;
  border: 1px solid var(--line);
  border-radius: 22px;
  background: rgba(255, 255, 255, 0.035);
  box-shadow: 0 14px 34px rgba(0, 0, 0, 0.28);
  transition: border-color 0.16s ease, box-shadow 0.16s ease;
}

.composer__shell:focus-within {
  border-color: rgba(139, 140, 248, 0.42);
  box-shadow: 0 0 0 4px rgba(99, 102, 241, 0.09), 0 14px 34px rgba(0, 0, 0, 0.3);
}

.composer__input {
  flex: 1;
  min-width: 0;
  max-height: 220px;
  padding: 8px 0;
  border: 0;
  background: transparent;
  color: var(--text);
  font-size: 0.92rem;
  line-height: 1.5;
  resize: none;
  outline: none;
}

.composer__input::placeholder {
  color: #6f7480;
}

.composer__actions {
  display: flex;
  align-items: center;
}

.composer__send {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border: 0;
  border-radius: 50%;
  background: var(--text);
  color: #0b0c10;
  cursor: pointer;
  transition: opacity 0.15s ease, transform 0.15s ease;
}

.composer__send:hover:not(:disabled) {
  transform: translateY(-1px);
}

.composer__send:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.composer__send--stop {
  background: rgba(255, 255, 255, 0.14);
  color: var(--text);
}

.composer__hint {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin: 0 8px;
  color: var(--faint);
  font-size: 0.7rem;
}

.composer__hint kbd {
  padding: 1px 4px;
  border: 1px solid var(--line);
  border-radius: 4px;
  font-family: inherit;
  font-size: 0.66rem;
}

.composer__status {
  max-width: 45%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.composer__status.is-offline {
  color: var(--amber);
}

/* Transcript */
.conversation {
  display: flex;
  flex-direction: column;
  gap: 24px;
  padding: 12px 0 8px;
}

.message {
  display: flex;
  gap: 12px;
  animation: fade-in 0.25s ease;
}

.message--user {
  justify-content: flex-end;
}

.message__bubble {
  max-width: 82%;
  padding: 10px 14px;
  border: 1px solid var(--line);
  border-radius: 18px 18px 6px 18px;
  background: rgba(255, 255, 255, 0.065);
  font-size: 0.9rem;
  line-height: 1.55;
  white-space: pre-wrap;
  word-break: break-word;
}

.message--assistant {
  align-items: flex-start;
}

.message__avatar {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  flex: none;
  margin-top: 3px;
  border-radius: 8px;
  background: linear-gradient(140deg, #6366f1, #8b5cf6);
  color: #f8f8ff;
}

.message__body {
  flex: 1;
  min-width: 0;
  font-size: 0.92rem;
  line-height: 1.62;
  color: #e8e9ed;
}

.message__actions {
  display: flex;
  gap: 4px;
  margin-top: 6px;
  opacity: 0;
  transition: opacity 0.15s ease;
}

.message:hover .message__actions,
.message:focus-within .message__actions {
  opacity: 1;
}

.quiet-action {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 7px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--faint);
  font-size: 0.74rem;
  cursor: pointer;
}

.quiet-action:hover {
  background: rgba(255, 255, 255, 0.055);
  color: var(--text);
}

.traces {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 12px 0 0;
  padding: 0;
  list-style: none;
}

.trace {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  max-width: 100%;
  padding: 3px 9px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.02);
  color: var(--faint);
  font-size: 0.71rem;
}

.trace__dot {
  width: 5px;
  height: 5px;
  flex: none;
  border-radius: 50%;
  background: var(--accent);
}

.trace__preview {
  max-width: 30ch;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--muted);
}

.typing {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 0;
  color: var(--faint);
  font-size: 0.87rem;
}

.typing__dots {
  display: inline-flex;
  gap: 3px;
}

.typing__dots i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
  animation: dot-pulse 1.2s infinite ease-in-out;
}

.typing__dots i:nth-child(2) {
  animation-delay: 0.15s;
}

.typing__dots i:nth-child(3) {
  animation-delay: 0.3s;
}

.caret {
  display: inline-block;
  width: 7px;
  height: 1em;
  margin-left: 2px;
  border-radius: 1px;
  background: var(--accent);
  vertical-align: text-bottom;
  animation: caret-blink 1s steps(1) infinite;
}

/* Markdown */
.md > *:first-child {
  margin-top: 0;
}

.md > *:last-child {
  margin-bottom: 0;
}

.md-paragraph {
  margin: 0 0 10px;
}

.md-heading {
  margin: 16px 0 8px;
  font-size: 1rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}

.md-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 0 0 10px;
  padding-left: 20px;
}

.md-code {
  padding: 1px 5px;
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.085);
  font-family: var(--mono);
  font-size: 0.85em;
}

.md-pre {
  margin: 0 0 10px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(0, 0, 0, 0.35);
  overflow-x: auto;
  font-size: 0.82rem;
  line-height: 1.5;
}

.md-pre code {
  font-family: var(--mono);
}

.md-quote {
  margin: 0 0 10px;
  padding-left: 12px;
  border-left: 2px solid var(--line-strong);
  color: var(--muted);
}

.md-rule {
  margin: 14px 0;
  border: 0;
  border-top: 1px solid var(--line);
}

/* Panel content primitives */
.stack {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.metric {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--surface);
}

.metric__label {
  font-size: 0.64rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--faint);
}

.metric__value {
  font-size: 1.25rem;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.chip {
  padding: 4px 10px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: transparent;
  color: var(--muted);
  font-size: 0.73rem;
  cursor: pointer;
}

.chip:hover {
  color: var(--text);
  border-color: var(--line-strong);
}

.chip.is-on {
  background: var(--surface-hover);
  border-color: var(--line-strong);
  color: var(--text);
}

.cards {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.card {
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.022);
  transition: border-color 0.15s ease, background 0.15s ease;
}

.card:hover {
  border-color: var(--line-strong);
  background: rgba(255, 255, 255, 0.035);
}

.card--hot {
  border-color: rgba(240, 179, 74, 0.28);
  background: rgba(240, 179, 74, 0.045);
}

.card__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.card__id {
  font-family: var(--mono);
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--accent);
}

metadata.preview:
.card__statement {
  margin: 8px 0;
  font-size: 0.885rem;
  line-height: 1.5;
}

.card__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin: 0 0 8px;
  color: var(--faint);
  font-size: 0.71rem;
}

.card__meta b {
  color: var(--muted);
  font-weight: 600;
}

display.text:
.card__statement {
  margin: 8px 0;
  font-size: 0.885rem;
  line-height: 1.5;
}

.card__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin: 0 0 8px;
  color: var(--faint);
  font-size: 0.71rem;
}

.card__meta b {
  color: var(--muted);
  font-weight: 600;
}

.card__evidence {
  margin: 0 0 8px;
  padding-left: 10px;
  border-left: 2px solid var(--line-strong);
  color: var(--muted);
  font-size: 0.78rem;
  line-height: 1.5;
}

.card__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.badge {
  padding: 2px 8px;
  border: 1px solid transparent;
  border-radius: 999px;
  font-size: 0.65rem;
  font-weight: 600;
  white-space: nowrap;
}

.badge--amber {
  border-color: rgba(240, 179, 74, 0.3);
  background: rgba(240, 179, 74, 0.12);
  color: var(--amber);
}

.badge--green {
  border-color: rgba(74, 222, 128, 0.25);
  background: rgba(74, 222, 128, 0.1);
  color: var(--green);
}

.badge--blue {
  border-color: rgba(139, 140, 248, 0.3);
  background: rgba(99, 102, 241, 0.12);
  color: var(--accent);
}

/* Job map */
.phases {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.phase {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 9px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--faint);
  font-size: 0.7rem;
}

.phase__index {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 0.65rem;
}

.steps {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.step {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 9px 12px;
  border-left: 2px solid rgba(139, 140, 248, 0.5);
  border-radius: 0 10px 10px 0;
  background: var(--surface);
  font-size: 0.85rem;
}

.step__order {
  flex: none;
  font-family: var(--mono);
  font-size: 0.7rem;
  color: var(--accent);
}

.empty-note {
  margin: 0;
  color: var(--faint);
  font-size: 0.78rem;
  line-height: 1.55;
}

/* Forms */
.form {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin-bottom: 2px;
}

.field label {
  font-size: 0.74rem;
  color: var(--muted);
}

.field__hint {
  margin: 0;
  color: var(--faint);
  font-size: 0.7rem;
  line-height: 1.45;
}

.input,
.select {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.25);
  color: var(--text);
  font-size: 0.84rem;
}

.input:hover,
.select:hover {
  border-color: var(--line-strong);
}

input[type="range"] {
  width: 100%;
  accent-color: var(--accent);
}

.button {
  padding: 8px 12px;
  border: 1px solid rgba(139, 140, 248, 0.4);
  border-radius: 9px;
  background: rgba(99, 102, 241, 0.16);
  color: var(--text);
  font-size: 0.82rem;
  cursor: pointer;
  transition: background 0.14s ease;
}

.button:hover:not(:disabled) {
  background: rgba(99, 102, 241, 0.26);
}

.button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.button--ghost {
  border-color: var(--line);
  background: transparent;
}

.button--ghost:hover:not(:disabled) {
  background: var(--surface-hover);
}

.button--block {
  width: 100%;
}

.disclosure {
  padding-top: 6px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 0.8rem;
}

.disclosure summary {
  cursor: pointer;
  color: var(--muted);
  font-size: 0.78rem;
  list-style: none;
}

.disclosure summary::-webkit-details-marker {
  display: none;
}

.disclosure summary::before {
  content: "+ ";
  color: var(--faint);
}

.disclosure[open] summary::before {
  content: "− ";
}

.disclosure > * + * {
  margin-top: 10px;
}

.disclosure p {
  color: var(--faint);
  font-size: 0.76rem;
  line-height: 1.55;
}

/* Impact */
.before-after {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.compare {
  padding: 11px 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
  font-size: 0.76rem;
}

.compare--before {
  border-color: rgba(248, 113, 113, 0.2);
  background: rgba(239, 68, 68, 0.06);
}

.compare--after {
  border-color: rgba(74, 222, 128, 0.2);
  background: rgba(16, 185, 129, 0.06);
}

.compare__label {
  display: block;
  margin-bottom: 6px;
  font-size: 0.63rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--faint);
}

.compare ul {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin: 0;
  padding-left: 15px;
  color: var(--muted);
  line-height: 1.45;
}

.compare b {
  color: var(--text);
  font-weight: 600;
}

.score-preview {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin: 0;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--surface);
  font-size: 0.78rem;
  color: var(--faint);
}

.score-preview b {
  color: var(--text);
  font-family: var(--mono);
  font-size: 0.95rem;
}

/* Evidence */
.notice {
  margin: 0;
  padding: 9px 11px;
  border: 1px solid rgba(240, 179, 74, 0.2);
  border-radius: 10px;
  background: rgba(240, 179, 74, 0.06);
  color: #d6c19b;
  font-size: 0.74rem;
  line-height: 1.5;
}

.evidence {
  margin: 0;
  padding: 11px 13px;
  border-left: 2px solid rgba(139, 140, 248, 0.5);
  border-radius: 0 10px 10px 0;
  background: var(--surface);
}

.evidence figcaption {
  margin-bottom: 5px;
  color: var(--muted);
  font-size: 0.72rem;
  font-weight: 600;
}

.evidence blockquote {
  margin: 0;
  color: #dfe1e7;
  font-size: 0.83rem;
  font-style: italic;
  line-height: 1.55;
}

.evidence__meta {
  display: block;
  margin-top: 7px;
  color: var(--faint);
  font-size: 0.68rem;
}

/* Settings */
.settings {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.settings__title {
  margin: 8px 0 0;
  color: var(--faint);
  font-size: 0.66rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.connection-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.connection-list li {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  border-radius: 8px;
  color: var(--muted);
  font-size: 0.76rem;
}

.connection-list li:hover {
  background: var(--surface);
}

.connection-list__value {
  margin-left: auto;
  color: var(--faint);
  font-size: 0.7rem;
}

.settings__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.muted {
  color: var(--faint);
  font-size: 0.72rem;
}

/* ------------------------------------------------------------------ */
/* Toasts                                                             */
/* ------------------------------------------------------------------ */
.toast-stack {
  position: fixed;
  right: 18px;
  bottom: 18px;
  z-index: 1000;
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-width: 360px;
}

.toast {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 12px;
  border: 1px solid var(--line-strong);
  border-radius: 11px;
  background: rgba(16, 18, 23, 0.96);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.45);
  color: var(--text);
  font-size: 0.8rem;
}

.toast--success {
  border-color: rgba(74, 222, 128, 0.4);
}

.toast--error {
  border-color: rgba(248, 113, 113, 0.4);
}

.toast--info {
  border-color: rgba(139, 140, 248, 0.4);
}

.toast button {
  border: 0;
  background: transparent;
  color: var(--faint);
  font-size: 0.9rem;
  cursor: pointer;
}

/* ------------------------------------------------------------------ */
/* Error fallback                                                     */
/* ------------------------------------------------------------------ */
.error-page {
  display: grid;
  place-items: center;
  min-height: 100dvh;
  padding: 24px;
  background: var(--bg);
}

.error-page__card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  max-width: 440px;
  text-align: center;
}

.error-page__title {
  margin: 0;
  font-size: clamp(1.3rem, 3vw, 1.7rem);
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.25;
}

/* ------------------------------------------------------------------ */
/* Loading + motion                                                   */
/* ------------------------------------------------------------------ */
.skeleton {
  border-radius: 8px;
  background: linear-gradient(
    90deg,
    rgba(255, 255, 255, 0.03) 25%,
    rgba(255, 255, 255, 0.08) 50%,
    rgba(255, 255, 255, 0.03) 75%
  );
  background-size: 200% 100%;
  animation: shimmer 1.6s infinite ease-in-out;
}

.skeleton--tile {
  height: 58px;
}

.skeleton--line {
  height: 12px;
  margin-bottom: 8px;
}

@keyframes shimmer {
  0% {
    background-position: -200% 0;
  }
  100% {
    background-position: 200% 0;
  }
}

@keyframes hero-in {
  from {
    opacity: 0;
    transform: translateY(6px);
    filter: blur(2px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
    filter: blur(0);
  }
}

/* ------------------------------------------------------------------ */
/* Offline                                                            */
/* ------------------------------------------------------------------ */
.offline {
  display: flex;
  flex: none;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px 16px;
  margin: 6px 22px 0;
  padding: 10px 14px;
  border: 1px solid rgba(245, 158, 11, 0.24);
  border-radius: 12px;
  background: rgba(245, 158, 11, 0.06);
  color: var(--muted);
  font-size: 0.78rem;
  line-height: 1.45;
}

.offline__text strong {
  color: var(--text);
}

.offline__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

/* ------------------------------------------------------------------ */
/* Transcript notices and tags                                        */
/* ------------------------------------------------------------------ */
.message--notice {
  display: block;
  padding: 12px 16px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(99, 102, 241, 0.055);
  font-size: 0.84rem;
}

.message--notice .markdown p:first-child {
  margin-top: 0;
}

.message--notice .markdown p:last-child {
  margin-bottom: 0;
}

.message__tag {
  display: inline-block;
  margin-bottom: 6px;
  padding: 2px 7px;
  border: 1px solid rgba(245, 158, 11, 0.3);
  border-radius: 999px;
  color: #f0b45a;
  font-size: 0.62rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* ------------------------------------------------------------------ */
/* Setup conversation                                                 */
/* ------------------------------------------------------------------ */
.chat--setup .chat__scroll {
  padding-top: 10px;
}

.setup {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding-top: 4px;
}

.setup__meta {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: calc(100% - 44px);
  max-width: 720px;
  margin: 6px auto 0;
  color: var(--faint);
  font-size: 0.7rem;
}

.setup__turns {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.setup__replies {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-left: 38px;
  padding-bottom: 4px;
  animation: fade-in 0.3s ease;
}

.suggestion--primary {
  border-color: rgba(139, 140, 248, 0.5);
  background: rgba(99, 102, 241, 0.16);
  color: var(--text);
}



/* ------------------------------------------------------------------ */
/* Manual data controls                                               */
/* ------------------------------------------------------------------ */
.step__name {
  flex: 1;
  min-width: 0;
}

.step__actions {
  display: flex;
  gap: 2px;
  margin-left: auto;
  opacity: 0;
  transition: opacity 0.14s ease;
}

.step:hover .step__actions,
.step:focus-within .step__actions {
  opacity: 1;
}

.step__edit {
  display: flex;
  flex: 1;
  align-items: center;
  gap: 6px;
}

.input--order {
  width: 68px;
  flex: none;
}

.input--area {
  min-height: 84px;
  padding: 9px 11px;
  line-height: 1.5;
  resize: vertical;
}

.button--danger {
  border-color: rgba(239, 68, 68, 0.35);
