}

/* ------------------------------------------------------------------ */
/* Step 1 — the three moves                                           */
/* ------------------------------------------------------------------ */

.wizard-moves {
  display: grid;
  gap: 10px;
  margin: 0 0 8px;
  padding: 0;
  list-style: none;
}

.wizard-move {
  display: grid;
  grid-template-columns: 44px 1fr;
  gap: 14px;
  padding: 13px 16px;
  border-radius: 12px;
  border: 1px solid var(--line);
  background: var(--surface);
}

.wizard-move__index {
