/* ------------------------------------------------------------------ */
/* First-run wizard — scoped to the onboarding module                 */
/* ------------------------------------------------------------------ */

.wizard-backdrop {
  position: fixed;
  inset: 0;
  z-index: 900;
  display: grid;
  place-items: center;
  padding: 24px;
  background: radial-gradient(
    120% 90% at 50% 0%,
    rgba(12, 14, 20, 0.7),
    rgba(4, 5, 8, 0.88)
  );
  backdrop-filter: blur(14px) saturate(120%);
  animation: wizard-fade 200ms ease-out both;
}

.wizard-panel {
  position: relative;
  width: min(720px, 100%);
  min-height: min(540px, 82vh);
  max-height: min(88vh, 760px);
  display: flex;
  flex-direction: column;
  border-radius: 20px;
  border: 1px solid var(--line-strong);
  background: linear-gradient(180deg, #101218 0%, #0a0b0e 100%);
  box-shadow:
    0 40px 120px -20px rgba(0, 0, 0, 0.85),
    0 0 0 1px rgba(0, 0, 0, 0.35),
    inset 0 1px 0 rgba(255, 255, 255, 0.05);
  overflow: hidden;
  animation: wizard-enter 320ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

.wizard-panel::before {
  content: "";
  position: absolute;
  pointer-events: none;
  top: -180px;
  right: 0;
  left: 0;
  height: 340px;
  background: radial-gradient(60% 100% at 50% 0%, rgba(139, 140, 248, 0.18), transparent 75%);
}

.wizard-panel:focus,
.wizard-title:focus {
  outline: none;
}

.wizard-head {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 22px 30px 14px;
}

.wizard-wordmark {
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--faint);
}

.wizard-count {
  font-size: 0.72rem;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

.wizard-progress {
  position: relative;
  z-index: 1;
  display: flex;
  gap: 5px;
  margin: 0;
  padding: 0 30px;
  list-style: none;
}

.wizard-progress__item {
  flex: 1;
  height: 2px;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.08);
}

.wizard-progress__item.is-done {
  background: rgba(139, 140, 248, 0.55);
}

.wizard-progress__item.is-current {
  background: linear-gradient(90deg, var(--accent-strong), rgba(139, 140, 248, 0.25));
}

.wizard-body {
  position: relative;
  z-index: 1;
  padding: 20px 30px 10px;
  overflow-y: auto;
  overscroll-behavior: contain;
  animation: wizard-rise 280ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

.wizard-title {
