import { useMemo, type ReactNode } from "react";

import { useStudio } from "../../state/StudioContext";
import type { WorkspacePanelId } from "../../types";
import { CompassIcon, RouteIcon, SignalIcon } from "../icons";

interface RailItem {
  id: WorkspacePanelId;
  label: string;
  count: number;
  noun: string;
  icon: ReactNode;
}

/**
 * The artifacts the conversation has produced, sitting above the conversation.
 *
 * This is deliberately not a tab bar: it has no fixed destinations, it derives
 * every chip from real state, and it renders nothing until the thread has made
 * something worth looking at. Clicking a chip is the "regular click" path for
 * people who prefer it; the conversation stays exactly where it was.
 */
export function WorkbenchRail() {
  const { canvas, activePanel, openPanel, closePanel } = useStudio();

  const items = useMemo<RailItem[]>(() => {
    const outcomes = canvas?.outcomes ?? [];
    const steps = canvas?.steps ?? [];
    const evidence = outcomes.filter((outcome) => outcome.evidence?.trim()).length;

    const rail: RailItem[] = [];
    if (outcomes.length > 0) {
      rail.push({
        id: "landscape",
        label: "Landscape",
        count: outcomes.length,
        noun: outcomes.length === 1 ? "opportunity" : "opportunities",
        icon: <CompassIcon size={14} />,
      });
    }
    if (steps.length > 0) {
      rail.push({
        id: "jobmap",
        label: "Job map",
        count: steps.length,
        noun: steps.length === 1 ? "step" : "steps",
        icon: <RouteIcon size={14} />,
      });
    }
    if (evidence > 0) {
      rail.push({
        id: "evidence",
        label: "Evidence",
        count: evidence,
        noun: evidence === 1 ? "signal" : "signals",
        icon: <SignalIcon size={14} />,
      });
    }
    return rail;
  }, [canvas]);

  if (items.length === 0) {
    return null;
  }

  return (
    <nav className="rail" aria-label="Your work">
      <ul className="rail__list">
        {items.map((item) => {
          const open = activePanel === item.id;
          return (
            <li key={item.id}>
              <button
                type="button"
                className={`rail__chip${open ? " is-open" : ""}`}
                aria-current={open ? "page" : undefined}
                aria-label={`${item.label}, ${item.count} ${item.noun}`}
                onClick={() => (open ? closePanel() : openPanel(item.id))}
              >
                <span className="rail__icon" aria-hidden="true">
                  {item.icon}
                </span>
                {item.label}
                <span className="rail__count">{item.count}</span>
              </button>
            </li>
          );
        })}
      </ul>
    </nav>
  );
}
=============== WorkspacePanel ===============
import { useStudio } from "../../state/StudioContext";
import { useMediaQuery } from "../../lib/useMediaQuery";
import { CloseIcon } from "../icons";
import { findPanel } from "./panels";

const MOBILE_QUERY = "(max-width: 1023px)";

/**
 * A lens on the conversation, not a place you go.
 *
 * On a wide screen it docks to the right and the thread keeps the stage: the
 * composer is still there, still focused, still usable. On a narrow screen
 * there is no room for both, so it becomes a sheet over the thread with a scrim
 * and a close control.
 */
export function WorkspacePanel() {
  const { activePanel, closePanel, sendMessage } = useStudio();
  const isMobile = useMediaQuery(MOBILE_QUERY);

  if (!activePanel) {
    return null;
  }

  const panel = findPanel(activePanel);

  function talk() {
    if (!panel.talk) {
      return;
    }
    closePanel();
    void sendMessage(panel.talk.intent);
  }

  return (
    <>
      {isMobile && (
        <button
          type="button"
          className="scrim"
          aria-label="Close workspace view"
          onClick={closePanel}
        />
      )}
      <aside
        className="lens"
        role={isMobile ? "dialog" : "complementary"}
        aria-modal={isMobile || undefined}
        aria-label={panel.title}
        key={panel.id}
      >
        <header className="lens__head">
          <div className="lens__heading">
            <span className="lens__icon" aria-hidden="true">
              {panel.icon}
            </span>
            <div>
              <h2 className="lens__title">{panel.title}</h2>
              <p className="lens__blurb">{panel.blurb}</p>
            </div>
          </div>
          <button
            type="button"
            className="icon-button"
            aria-label="Close workspace view"
            title="Close"
            onClick={closePanel}
          >
            <CloseIcon size={16} />
          </button>
        </header>

        <div className="lens__body">
          <div className="lens__content">{panel.render()}</div>
        </div>

        {panel.talk && (
          <footer className="lens__foot">
            <p className="lens__note">A lens on the conversation, not a separate place.</p>
            <button type="button" className="button button--block" onClick={talk}>
              {panel.talk.label}
            </button>
          </footer>
        )}
      </aside>
    </>
  );
}

