.composer__shell:focus-within {
  border-color: rgba(139, 140, 248, 0.42);
  box-shadow: 0 0 0 4px rgba(99, 102, 241, 0.09), 0 14px 34px rgba(0, 0, 0, 0.3);
}

.composer__input {
  flex: 1;
  min-width: 0;
  max-height: 220px;
  padding: 8px 0;
  border: 0;
  background: transparent;
  color: var(--text);
  font-size: 0.92rem;
  line-height: 1.5;
  resize: none;
  outline: none;
}

.composer__input::placeholder {
  color: #6f7480;
}

.composer__actions {
  display: flex;
  align-items: center;
}

.composer__send {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border: 0;
  border-radius: 50%;
  background: var(--text);
  color: #0b0c10;
  cursor: pointer;
  transition: opacity 0.15s ease, transform 0.15s ease;
}

.composer__send:hover:not(:disabled) {
  transform: translateY(-1px);
}

.composer__send:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.composer__send--stop {
  background: rgba(255, 255, 255, 0.14);
  color: var(--text);
}

.composer__hint {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin: 0 8px;
  color: var(--faint);
  font-size: 0.7rem;
}

.composer__hint kbd {
  padding: 1px 4px;
  border: 1px solid var(--line);
  border-radius: 4px;
  font-family: inherit;
  font-size: 0.66rem;
}

.composer__status {
  max-width: 45%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.composer__status.is-offline {
  color: var(--amber);
}

/* Transcript */
.conversation {
  display: flex;
  flex-direction: column;
  gap: 24px;
  padding: 12px 0 8px;
}

.message {
  display: flex;
  gap: 12px;
  animation: fade-in 0.25s ease;
}

.message--user {
  justify-content: flex-end;
}

.message__bubble {
  max-width: 82%;
  padding: 10px 14px;
  border: 1px solid var(--line);
  border-radius: 18px 18px 6px 18px;
  background: rgba(255, 255, 255, 0.065);
  font-size: 0.9rem;
  line-height: 1.55;
  white-space: pre-wrap;
  word-break: break-word;
}

.message--assistant {
  align-items: flex-start;
}

.message__avatar {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  flex: none;
  margin-top: 3px;
  border-radius: 8px;
  background: linear-gradient(140deg, #6366f1, #8b5cf6);
  color: #f8f8ff;
}

.message__body {
  flex: 1;
  min-width: 0;
  font-size: 0.92rem;
  line-height: 1.62;
  color: #e8e9ed;
}

.message__actions {
  display: flex;
  gap: 4px;
  margin-top: 6px;
  opacity: 0;
  transition: opacity 0.15s ease;
}

.message:hover .message__actions,
.message:focus-within .message__actions {
  opacity: 1;
}

.quiet-action {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 7px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--faint);
  font-size: 0.74rem;
  cursor: pointer;
}

.quiet-action:hover {
  background: rgba(255, 255, 255, 0.055);
  color: var(--text);
}

.traces {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 12px 0 0;
  padding: 0;
  list-style: none;
}

.trace {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  max-width: 100%;
  padding: 3px 9px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.02);
  color: var(--faint);
  font-size: 0.71rem;
}

.trace__dot {
  width: 5px;
  height: 5px;
  flex: none;
  border-radius: 50%;
  background: var(--accent);
}

.trace__preview {
  max-width: 30ch;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--muted);
}

.typing {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 0;
  color: var(--faint);
  font-size: 0.87rem;
}

.typing__dots {
  display: inline-flex;
  gap: 3px;
}

.typing__dots i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
  animation: dot-pulse 1.2s infinite ease-in-out;
}

.typing__dots i:nth-child(2) {
  animation-delay: 0.15s;
}

.typing__dots i:nth-child(3) {
  animation-delay: 0.3s;
}

.caret {
  display: inline-block;
  width: 7px;
  height: 1em;
  margin-left: 2px;
  border-radius: 1px;
  background: var(--accent);
  vertical-align: text-bottom;
  animation: caret-blink 1s steps(1) infinite;
}

/* Markdown */
.md > *:first-child {
  margin-top: 0;
}

.md > *:last-child {
  margin-bottom: 0;
}

.md-paragraph {
  margin: 0 0 10px;
}

.md-heading {
  margin: 16px 0 8px;
  font-size: 1rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}

.md-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 0 0 10px;
  padding-left: 20px;
}

.md-code {
  padding: 1px 5px;
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.085);
  font-family: var(--mono);
  font-size: 0.85em;
}

.md-pre {
  margin: 0 0 10px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(0, 0, 0, 0.35);
  overflow-x: auto;
  font-size: 0.82rem;
  line-height: 1.5;
}

.md-pre code {
  font-family: var(--mono);
}

.md-quote {
  margin: 0 0 10px;
  padding-left: 12px;
  border-left: 2px solid var(--line-strong);
  color: var(--muted);
}

.md-rule {
  margin: 14px 0;
  border: 0;
  border-top: 1px solid var(--line);
}

/* Panel content primitives */
.stack {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.metric {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--surface);
}

.metric__label {
  font-size: 0.64rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--faint);
}

.metric__value {
  font-size: 1.25rem;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.chip {
  padding: 4px 10px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: transparent;
  color: var(--muted);
  font-size: 0.73rem;
  cursor: pointer;
}

.chip:hover {
  color: var(--text);
  border-color: var(--line-strong);
}

.chip.is-on {
  background: var(--surface-hover);
  border-color: var(--line-strong);
  color: var(--text);
}

.cards {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.card {
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.022);
  transition: border-color 0.15s ease, background 0.15s ease;
}

.card:hover {
  border-color: var(--line-strong);
  background: rgba(255, 255, 255, 0.035);
}

.card--hot {
  border-color: rgba(240, 179, 74, 0.28);
  background: rgba(240, 179, 74, 0.045);
}

.card__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.card__id {
  font-family: var(--mono);
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--accent);
}

.card__statement {
  margin: 8px 0;
  font-size: 0.885rem;
  line-height: 1.5;
}

.card__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin: 0 0 8px;
  color: var(--faint);
  font-size: 0.71rem;
}

.card__meta b {
  color: var(--muted);
  font-weight: 600;
}

.card__evidence {
  margin: 0 0 8px;
  padding-left: 10px;
  border-left: 2px solid var(--line-strong);
  color: var(--muted);
  font-size: 0.78rem;
  line-height: 1.5;
}

.card__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.badge {
  padding: 2px 8px;
  border: 1px solid transparent;
  border-radius: 999px;
  font-size: 0.65rem;
  font-weight: 600;
  white-space: nowrap;
}

.badge--amber {
  border-color: rgba(240, 179, 74, 0.3);
  background: rgba(240, 179, 74, 0.12);
  color: var(--amber);
}

.badge--green {
  border-color: rgba(74, 222, 128, 0.25);
  background: rgba(74, 222, 128, 0.1);
  color: var(--green);
}

.badge--blue {
  border-color: rgba(139, 140, 248, 0.3);
  background: rgba(99, 102, 241, 0.12);
  color: var(--accent);
}

/* Job map */
.phases {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.phase {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 9px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--faint);
  font-size: 0.7rem;
}

.phase__index {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 0.65rem;
}

.steps {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.step {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 9px 12px;
  border-left: 2px solid rgba(139, 140, 248, 0.5);
  border-radius: 0 10px 10px 0;
  background: var(--surface);
  font-size: 0.85rem;
}

.step__order {
  flex: none;
  font-family: var(--mono);
  font-size: 0.7rem;
  color: var(--accent);
}

.empty-note {
  margin: 0;
  color: var(--faint);
  font-size: 0.78rem;
  line-height: 1.55;
}

/* Forms */
.form {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin-bottom: 2px;
}

.field label {
  font-size: 0.74rem;
  color: var(--muted);
}

.field__hint {
  margin: 0;
  color: var(--faint);
  font-size: 0.7rem;
  line-height: 1.45;
}

.input,
.select {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.25);
  color: var(--text);
  font-size: 0.84rem;
}

.input:hover,
.select:hover {
  border-color: var(--line-strong);
}

input[type="range"] {
  width: 100%;
  accent-color: var(--accent);
}

.button {
  padding: 8px 12px;
  border: 1px solid rgba(139, 140, 248, 0.4);
  border-radius: 9px;
  background: rgba(99, 102, 241, 0.16);
  color: var(--text);
  font-size: 0.82rem;
  cursor: pointer;
  transition: background 0.14s ease;
}

.button:hover:not(:disabled) {
  background: rgba(99, 102, 241, 0.26);
}

.button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.button--ghost {
  border-color: var(--line);
  background: transparent;
}

.button--ghost:hover:not(:disabled) {
  background: var(--surface-hover);
}

.button--block {
  width: 100%;
}

.disclosure {
  padding-top: 6px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 0.8rem;
}

.disclosure summary {
  cursor: pointer;
  color: var(--muted);
  font-size: 0.78rem;
  list-style: none;
}

.disclosure summary::-webkit-details-marker {
  display: none;
}

.disclosure summary::before {
  content: "+ ";
  color: var(--faint);
}

.disclosure[open] summary::before {
  content: "− ";
}

.disclosure > * + * {
  margin-top: 10px;
}

.disclosure p {
  color: var(--faint);
  font-size: 0.76rem;
  line-height: 1.55;
}

/* Impact */
.before-after {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.compare {
  padding: 11px 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
  font-size: 0.76rem;
}

.compare--before {
  border-color: rgba(248, 113, 113, 0.2);
  background: rgba(239, 68, 68, 0.06);
}

.compare--after {
  border-color: rgba(74, 222, 128, 0.2);
  background: rgba(16, 185, 129, 0.06);
}

.compare__label {
  display: block;
  margin-bottom: 6px;
  font-size: 0.63rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--faint);
}

.compare ul {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin: 0;
  padding-left: 15px;
  color: var(--muted);
  line-height: 1.45;
}

.compare b {
  color: var(--text);
  font-weight: 600;
}

.score-preview {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin: 0;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--surface);
  font-size: 0.78rem;
  color: var(--faint);
}

.score-preview b {
  color: var(--text);
  font-family: var(--mono);
  font-size: 0.95rem;
}

/* Evidence */
.notice {
  margin: 0;
  padding: 9px 11px;
  border: 1px solid rgba(240, 179, 74, 0.2);
  border-radius: 10px;
  background: rgba(240, 179, 74, 0.06);
  color: #d6c19b;
  font-size: 0.74rem;
  line-height: 1.5;
}

.evidence {
  margin: 0;
  padding: 11px 13px;
  border-left: 2px solid rgba(139, 140, 248, 0.5);
  border-radius: 0 10px 10px 0;
  background: var(--surface);
}

.evidence figcaption {
  margin-bottom: 5px;
  color: var(--muted);
  font-size: 0.72rem;
  font-weight: 600;
}

.evidence blockquote {
  margin: 0;
  color: #dfe1e7;
  font-size: 0.83rem;
  font-style: italic;
  line-height: 1.55;
}

.evidence__meta {
  display: block;
  margin-top: 7px;
  color: var(--faint);
  font-size: 0.68rem;
}

/* Settings */
.settings {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.settings__title {
  margin: 8px 0 0;
  color: var(--faint);
  font-size: 0.66rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.connection-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.connection-list li {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  border-radius: 8px;
  color: var(--muted);
  font-size: 0.76rem;
}

.connection-list li:hover {
  background: var(--surface);
}

.connection-list__value {
  margin-left: auto;
  color: var(--faint);
  font-size: 0.7rem;
}

.settings__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.muted {
  color: var(--faint);
  font-size: 0.72rem;
}

/* ------------------------------------------------------------------ */
/* Toasts                                                             */
/* ------------------------------------------------------------------ */
.toast-stack {
  position: fixed;
  right: 18px;
  bottom: 18px;
  z-index: 1000;
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-width: 360px;
}

.toast {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 12px;
  border: 1px solid var(--line-strong);
  border-radius: 11px;
  background: rgba(16, 18, 23, 0.96);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.45);
  color: var(--text);
  font-size: 0.8rem;
}

.toast--success {
  border-color: rgba(74, 222, 128, 0.4);
}

.toast--error {
  border-color: rgba(248, 113, 113, 0.4);
}

.toast--info {
  border-color: rgba(139, 140, 248, 0.4);
}

.toast button {
  border: 0;
  background: transparent;
  color: var(--faint);
  font-size: 0.9rem;
  cursor: pointer;
}

/* ------------------------------------------------------------------ */
/* Error fallback                                                     */
/* ------------------------------------------------------------------ */
.error-page {
  display: grid;
  place-items: center;
  min-height: 100dvh;
  padding: 24px;
  background: var(--bg);
}

.error-page__card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  max-width: 440px;
  text-align: center;
}

.error-page__title {
  margin: 0;
  font-size: clamp(1.3rem, 3vw, 1.7rem);
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.25;
}

/* ------------------------------------------------------------------ */
/* Loading + motion                                                   */
/* ------------------------------------------------------------------ */
.skeleton {
  border-radius: 8px;
  background: linear-gradient(
    90deg,
    rgba(255, 255, 255, 0.03) 25%,
    rgba(255, 255, 255, 0.08) 50%,
    rgba(255, 255, 255, 0.03) 75%
  );
  background-size: 200% 100%;
  animation: shimmer 1.6s infinite ease-in-out;
}

.skeleton--tile {
  height: 58px;
}

.skeleton--line {
  height: 12px;
  margin-bottom: 8px;
}

@keyframes shimmer {
  0% {
    background-position: -200% 0;
  }
  100% {
    background-position: 200% 0;
  }
}

@keyframes hero-in {
  from {
    opacity: 0;
    transform: translateY(6px);
    filter: blur(2px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
    filter: blur(0);
  }
}

/* ------------------------------------------------------------------ */
/* Offline                                                            */
/* ------------------------------------------------------------------ */
.offline {
  display: flex;
  flex: none;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px 16px;
  margin: 6px 22px 0;
  padding: 10px 14px;
  border: 1px solid rgba(245, 158, 11, 0.24);
  border-radius: 12px;
  background: rgba(245, 158, 11, 0.06);
  color: var(--muted);
  font-size: 0.78rem;
  line-height: 1.45;
}

.offline__text strong {
  color: var(--text);
}

.offline__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

/* ------------------------------------------------------------------ */
/* Transcript notices and tags                                        */
/* ------------------------------------------------------------------ */
.message--notice {
  display: block;
  padding: 12px 16px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(99, 102, 241, 0.055);
  font-size: 0.84rem;
}

.message--notice .markdown p:first-child {
  margin-top: 0;
}

.message--notice .markdown p:last-child {
  margin-bottom: 0;
}

.message__tag {
  display: inline-block;
  margin-bottom: 6px;
  padding: 2px 7px;
  border: 1px solid rgba(245, 158, 11, 0.3);
  border-radius: 999px;
  color: #f0b45a;
  font-size: 0.62rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* ------------------------------------------------------------------ */
/* Setup conversation                                                 */
/* ------------------------------------------------------------------ */
.chat--setup .chat__scroll {
  padding-top: 10px;
}

.setup {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding-top: 4px;
}

.setup__meta {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: calc(100% - 44px);
  max-width: 720px;
  margin: 6px auto 0;
  color: var(--faint);
  font-size: 0.7rem;
}

.setup__turns {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.setup__replies {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-left: 38px;
  padding-bottom: 4px;
  animation: fade-in 0.3s ease;
}

.suggestion--primary {
  border-color: rgba(139, 140, 248, 0.5);
  background: rgba(99, 102, 241, 0.16);
  color: var(--text);
}



/* ------------------------------------------------------------------ */
/* Manual data controls                                               */
/* ------------------------------------------------------------------ */
.step__name {
  flex: 1;
  min-width: 0;
}

.step__actions {
  display: flex;
  gap: 2px;
  margin-left: auto;
  opacity: 0;
  transition: opacity 0.14s ease;
}

.step:hover .step__actions,
.step:focus-within .step__actions {
  opacity: 1;
}

.step__edit {
  display: flex;
  flex: 1;
  align-items: center;
  gap: 6px;
}

.input--order {
  width: 68px;
  flex: none;
}

.input--area {
  min-height: 84px;
  padding: 9px 11px;
  line-height: 1.5;
  resize: vertical;
}

.button--danger {
  border-color: rgba(239, 68, 68, 0.35);
  background: rgba(239, 68, 68, 0.12);
}

.button--danger:hover:not(:disabled) {
  background: rgba(239, 68, 68, 0.2);
}

.quiet-action--danger:hover {
  color: #fca5a5;
}

.suggestion--quiet {
  border-style: dashed;
  color: var(--faint);
}

.card__edit {
  display: grid;
  gap: 10px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.02);
}

.card__slider {
  display: grid;
  gap: 6px;
  color: var(--muted);
  font-size: 0.74rem;
}

.card__edit-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.settings__context {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(99, 102, 241, 0.06);
}

.settings__context-label {
  margin: 0 0 3px;
  color: var(--faint);
  font-size: 0.64rem;
  font-weight: 600;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.settings__context-value {
  margin: 0;
  color: var(--muted);
  font-size: 0.8rem;
  line-height: 1.45;
}

/* ------------------------------------------------------------------ */
/* Bell & Notification Badges                                         */
/* ------------------------------------------------------------------ */

.bell-badge {
  position: absolute;
  top: -2px;
  right: -2px;
  display: grid;
  place-items: center;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  border-radius: 999px;
  background: var(--accent-strong);
  color: #ffffff;
  font-size: 0.62rem;
  font-weight: 700;
  box-shadow: 0 0 8px rgba(99, 102, 241, 0.6);
  animation: pulse-badge 2s infinite ease-in-out;
}

@keyframes pulse-badge {
  0%, 100% {
    transform: scale(1);
    box-shadow: 0 0 6px rgba(99, 102, 241, 0.5);
  }
  50% {
    transform: scale(1.1);
    box-shadow: 0 0 12px rgba(139, 140, 248, 0.8);
  }
}

.catchup-feed {
  animation: fade-in 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}

.catchup-summary {
  background: linear-gradient(135deg, rgba(99, 102, 241, 0.08) 0%, rgba(255, 255, 255, 0.01) 100%);
  border-color: rgba(139, 140, 248, 0.25);
  backdrop-filter: blur(12px);
}

.catchup-summary__actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.catchup-card {
  position: relative;
  transition: all 0.2s ease-in-out;
}

.catchup-card:hover {
  transform: translateY(-1px);
  border-color: var(--line-strong);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.3);
}

.catchup-card.is-unread {
  border-left: 3px solid var(--accent);
  background: rgba(99, 102, 241, 0.04);
}

@media (max-width: 1023px) {
  .lens {
    position: fixed;
    inset: 0;
    z-index: 60;
    width: 100%;
    max-width: none;
    border-left: 0;
    background: var(--bg);
    box-shadow: none;
  }

  .lens__head {
    padding: 14px 16px;
  }

  .lens__body {
    padding: 18px 16px 32px;
  }

  .rail {
    padding-inline: 18px;
  }

  .setup__meta {
    width: calc(100% - 36px);
  }

  .setup__replies {
    margin-left: 0;
  }

  .offline {
    margin-inline: 14px;
  }

  .chat__welcome {
    padding: 12px 18px 40px;
  }

  .chat__scroll {
    padding-inline: 18px;
  }

  .chat__dock {
    padding-inline: 12px;
  }

  .composer__hint span:first-child {
    display: none;
  }

  .composer__status {
    max-width: 100%;
  }

  .before-after {
    grid-template-columns: 1fr;
  }
}

@media (hover: none) {
  .message__actions {
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
}

/* ------------------------------------------------------------------ */
/* Apple-inspired polish & Glassmorphism refinements                   */
/* ------------------------------------------------------------------ */

.outcome-card {
  transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  background: var(--studio-surface);
  border: 1px solid var(--studio-border);
  border-radius: var(--studio-radius);
  padding: 16px;
  backdrop-filter: blur(12px);
}

.outcome-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4), 0 0 1px rgba(255, 255, 255, 0.2);
  border-color: rgba(255, 255, 255, 0.16);
}

.pulsing-card {
  box-shadow: 0 0 20px rgba(251, 191, 36, 0.15);
  border-color: rgba(251, 191, 36, 0.3);
}

.studio-button {
  transition: all 0.15s ease-in-out;
  font-weight: 500;
  letter-spacing: -0.01em;
}

.studio-button:hover:not(:disabled) {
  transform: scale(1.02);
  opacity: 0.95;
}

.studio-button:active:not(:disabled) {
  transform: scale(0.98);
}

.studio-button--primary {
  background: linear-gradient(135deg, var(--studio-indigo) 0%, var(--studio-indigo-strong) 100%);
  color: #ffffff;
  box-shadow: 0 2px 8px rgba(99, 102, 241, 0.3);
}

.studio-metric {
  background: rgba(255, 255, 255, 0.02);
  border: 1px solid var(--studio-border);
  border-radius: 10px;
  padding: 14px;
  backdrop-filter: blur(8px);
}

/* Custom scrollbar for data density tables */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: rgba(0, 0, 0, 0.2);
}

::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.15);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.3);
}

/* ------------------------------------------------------------------ */
/* Agent-composed surfaces                                            */
/* ------------------------------------------------------------------ */
.ui-code {
  font-family: var(--mono);
  font-size: 0.86em;
  background: rgba(148, 163, 184, 0.14);
  padding: 1px 5px;
  border-radius: 4px;
}

/* ------------------------------------------------------------------ */
/* Generated surfaces                                                 */
/* ------------------------------------------------------------------ */
.ui-surface {
  animation: surface-enter 0.28s cubic-bezier(0.16, 1, 0.3, 1) both;
  min-width: 0;
}

@keyframes surface-enter {
  from {
    opacity: 0;
    transform: translateY(6px);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

.ui-stack {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.ui-stack--horizontal {
  flex-direction: row;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-start;
}

.ui-grid {
  display: grid;
  min-width: 0;
}

.ui-grid--2 {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.ui-grid--3 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.ui-gap--sm {
  gap: 8px;
}

.ui-gap--md {
  gap: 12px;
}

.ui-gap--lg {
  gap: 18px;
}

.ui-heading {
  margin: 0;
  font-size: 0.95rem;
}

.ui-text {
  font-size: 0.92rem;
  line-height: 1.55;
}

.ui-text--muted {
  color: var(--studio-muted);
}

.ui-text--positive {
  color: var(--studio-green);
}

.ui-text--warning {
  color: var(--studio-amber);
}

.ui-text--critical {
  color: var(--studio-red);
}

.ui-caption {
  margin: 0;
  font-size: 0.72rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--studio-muted);
}

/* Cards */
.ui-card {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px 18px;
  border-radius: 14px;
  border: 1px solid var(--studio-border);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.045), rgba(255, 255, 255, 0.015));
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.04) inset, 0 12px 30px -26px rgba(0, 0, 0, 0.9);
  min-width: 0;
}

.ui-card--urgent {
  border-color: rgba(251, 191, 36, 0.28);
  box-shadow: 0 0 0 1px rgba(251, 191, 36, 0.05), 0 18px 44px -30px rgba(251, 191, 36, 0.45);
}

.ui-card--unknown {
  background: transparent;
  border-style: dashed;
  gap: 4px;
}

.ui-card__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.ui-card__id {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--studio-indigo);
}

.ui-card__statement {
  margin: 0;
  font-size: 0.98rem;
  font-weight: 500;
  line-height: 1.45;
}

.ui-card__title {
  margin: 0;
  font-size: 1rem;
}

.ui-card__formula {
  margin: 0;
  font-size: 0.72rem;
  color: var(--studio-muted);
  font-variant-numeric: tabular-nums;
}

.ui-card__meters {
  display: grid;
  gap: 8px;
}

.ui-card__evidence {
  margin: 0;
  padding: 10px 12px;
  border-left: 2px solid rgba(129, 140, 248, 0.5);
  background: rgba(15, 23, 42, 0.5);
  border-radius: 0 8px 8px 0;
  font-size: 0.84rem;
  color: #cbd5e1;
}

/* Pills */
.ui-pill {
  display: inline-flex;
  align-items: center;
  padding: 3px 9px;
  border-radius: 9999px;
  border: 1px solid transparent;
  font-size: 0.72rem;
  font-weight: 600;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.ui-pill--neutral {
  background: rgba(148, 163, 184, 0.12);
  border-color: rgba(148, 163, 184, 0.22);
  color: #cbd5e1;
}

.ui-pill--positive {
  background: rgba(52, 211, 153, 0.12);
  border-color: rgba(52, 211, 153, 0.28);
  color: var(--studio-green);
}

.ui-pill--warning {
  background: rgba(251, 191, 36, 0.12);
  border-color: rgba(251, 191, 36, 0.3);
  color: var(--studio-amber);
}

.ui-pill--critical {
  background: rgba(248, 113, 113, 0.12);
  border-color: rgba(248, 113, 113, 0.3);
  color: var(--studio-red);
}

.ui-pill--info {
  background: rgba(129, 140, 248, 0.12);
  border-color: rgba(129, 140, 248, 0.3);
  color: var(--studio-indigo);
}

/* Meters */
.ui-meter__head {
  display: flex;
  justify-content: space-between;
  font-size: 0.74rem;
  color: var(--studio-muted);
  margin-bottom: 4px;
}

.ui-meter__value {
  color: #cbd5e1;
  font-variant-numeric: tabular-nums;
}

.ui-meter__track {
  height: 5px;
  border-radius: 9999px;
  background: rgba(148, 163, 184, 0.14);
  overflow: hidden;
}

.ui-meter__fill {
  display: block;
  height: 100%;
  border-radius: 9999px;
  transition: width 0.4s cubic-bezier(0.16, 1, 0.3, 1);
}

.ui-tone-bg--neutral {
  background: #94a3b8;
}

.ui-tone-bg--positive {
  background: var(--studio-green);
}

.ui-tone-bg--warning {
  background: var(--studio-amber);
}

.ui-tone-bg--critical {
  background: var(--studio-red);
}

.ui-tone-bg--info {
  background: var(--studio-indigo);
}

/* Stats */
.ui-stat {
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid var(--studio-border);
  background: rgba(15, 23, 42, 0.5);
  min-width: 0;
}

.ui-stat__label {
  font-size: 0.68rem;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--studio-muted);
}

.ui-stat__value {
  margin-top: 3px;
  font-size: 1.15rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.ui-stat__delta {
  font-size: 0.72rem;
  color: var(--studio-muted);
}

.ui-stat.ui-tone--positive .ui-stat__value {
  color: var(--studio-green);
}

.ui-stat.ui-tone--warning .ui-stat__value {
  color: var(--studio-amber);
}

.ui-stat.ui-tone--critical .ui-stat__value {
  color: var(--studio-red);
}

/* Callouts */
.ui-callout {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 11px 13px;
  border-radius: 10px;
  border: 1px solid;
  border-left-width: 3px;
  font-size: 0.85rem;
}

.ui-callout--info {
  background: rgba(129, 140, 248, 0.07);
  border-color: rgba(129, 140, 248, 0.25);
}

.ui-callout--positive {
  background: rgba(52, 211, 153, 0.07);
  border-color: rgba(52, 211, 153, 0.25);
}

.ui-callout--warning {
  background: rgba(251, 191, 36, 0.07);
  border-color: rgba(251, 191, 36, 0.25);
}

.ui-callout--critical {
  background: rgba(248, 113, 113, 0.07);
  border-color: rgba(248, 113, 113, 0.25);
}

.ui-callout__title {
  font-size: 0.8rem;
  font-weight: 600;
}

/* Lists + divider */
.ui-list {
  margin: 0;
  padding-left: 18px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 0.88rem;
}

.ui-list--check {
  list-style: none;
  padding-left: 2px;
}

.ui-list--check li::before {
  content: "✓";
  color: var(--studio-green);
  margin-right: 7px;
  font-size: 0.8em;
}

.ui-divider {
  border: none;
  border-top: 1px solid var(--studio-border);
  margin: 2px 0;
  width: 100%;
}

/* Actions */
.ui-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.ui-action {
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 7px 12px;
  font-size: 0.82rem;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease,
    transform 0.1s ease;
}

.ui-action--primary {
  background: var(--studio-indigo-strong);
  border-color: rgba(255, 255, 255, 0.08);
  color: #fff;
}

.ui-action--primary:hover {
  background: #7c7ff5;
}

.ui-action--ghost {
  background: transparent;
  border-color: var(--studio-border);
  color: #cbd5e1;
}

.ui-action--ghost:hover {
  border-color: rgba(129, 140, 248, 0.45);
  color: var(--studio-text);
}

.ui-action:active {
  transform: translateY(1px);
}

.ui-action:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

/* Tables */
.ui-table-wrap {
  overflow-x: auto;
}

.ui-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.86rem;
}

.ui-table th {
  padding: 0 0 6px;
  border-bottom: 1px solid var(--studio-border);
  text-align: left;
  font-size: 0.66rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--studio-muted);
}

.ui-table td {
  padding: 9px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.04);
  vertical-align: top;
}

.ui-table tr:last-child td {
  border-bottom: none;
}

.ui-table td:first-child {
  padding-right: 12px;
}

.ui-table td:last-child {
  text-align: right;
  white-space: nowrap;
}

.ui-table .ui-card__id {
  display: block;
}

.ui-table__statement {
  display: block;
  margin-top: 3px;
  line-height: 1.4;
  color: #cbd5e1;
}

.ui-table__row--urgent .ui-card__id {
  color: var(--studio-amber);
}

/* Impact simulation */
.ui-bet {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 9px 12px;
  border-radius: 8px;
  border: 1px solid rgba(129, 140, 248, 0.2);
  background: rgba(129, 140, 248, 0.07);
}

.ui-bet__label {
  font-size: 0.64rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--studio-indigo);
  white-space: nowrap;
}

.ui-bet__value {
  font-size: 0.88rem;
  color: #e2e8f0;
}

.ui-phase {
  padding: 12px;
  border-radius: 10px;
  border: 1px solid;
  min-width: 0;
}

.ui-phase.ui-tone--critical {
  background: rgba(248, 113, 113, 0.06);
  border-color: rgba(248, 113, 113, 0.22);
}

.ui-phase.ui-tone--positive {
  background: rgba(52, 211, 153, 0.06);
  border-color: rgba(52, 211, 153, 0.22);
}

.ui-phase__label {
  margin-bottom: 7px;
  font-size: 0.64rem;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--studio-muted);
}

.ui-phase__items {
  margin: 0;
  padding-left: 16px;
  display: flex;
  flex-direction: column;
  gap: 5px;
  font-size: 0.84rem;
  color: #cbd5e1;
}

/* Evidence */
.ui-quote {
  margin: 0;
  padding-left: 12px;
  border-left: 2px solid rgba(129, 140, 248, 0.5);
  font-size: 0.95rem;
  font-style: italic;
  line-height: 1.55;
  color: #e2e8f0;
}

/* Job map */
.ui-jobmap {
  list-style: none;
  margin: 0;
  padding: 0;
}

.ui-jobmap__step {
  display: flex;
  gap: 10px;
  padding: 8px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.04);
}

.ui-jobmap__step:last-child {
  border-bottom: none;
}

.ui-jobmap__index {
  flex: none;
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  border-radius: 6px;
  background: rgba(129, 140, 248, 0.14);
  color: var(--studio-indigo);
  font-size: 0.7rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.ui-jobmap__body {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ui-jobmap__name {
  font-size: 0.88rem;
}

.ui-jobmap__stage {
  font-size: 0.64rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--studio-muted);
}

.ui-jobmap__note {
  font-size: 0.78rem;
  color: var(--studio-muted);
}

/* Decision record */
.ui-fields {
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.ui-field {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ui-field dt {
  font-size: 0.64rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--studio-muted);
}

.ui-field dd {
  margin: 0;
  font-size: 0.88rem;
  color: #e2e8f0;
}

@media (max-width: 640px) {
  .ui-grid--2,
  .ui-grid--3 {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (prefers-reduced-motion: reduce) {
  .ui-surface {
    animation: none;
  }

  .ui-meter__fill {
    transition: none;
  }
}

/* Markdown inside a surface. Cards are dense; paragraphs should hug. */
.ui-card .md-paragraph,
.ui-callout__body .md-paragraph,
.ui-card__evidence .md-paragraph,
.ui-quote .md-paragraph {
  margin: 0 0 6px;
}

.ui-card .md-paragraph:last-child,
.ui-callout__body .md-paragraph:last-child,
.ui-card__evidence .md-paragraph:last-child,
.ui-quote .md-paragraph:last-child {
  margin-bottom: 0;
}

.ui-card .md-list,
.ui-callout__body .md-list {
  margin: 4px 0 0;
}

/* A surface sits in the prose, not outside it. */
.message__body > .ui-surface {
  margin: 12px 0;
}

/* ------------------------------------------------------------------ */
/* Discrete Changelog Modal (Steve Jobs Quality)                     */
/* ------------------------------------------------------------------ */
.pill-changelog {
  background: rgba(129, 140, 248, 0.18);
  color: #a5b4fc;
  border: 1px solid rgba(129, 140, 248, 0.4);
  cursor: pointer;
  transition: all 0.2s ease;
}

.pill-changelog:hover {
  background: rgba(129, 140, 248, 0.3);
  border-color: #818cf8;
  color: #ffffff;
  box-shadow: 0 0 12px rgba(129, 140, 248, 0.25);
}

.changelog-overlay {
  position: fixed;
  inset: 0;
  z-index: 2000;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(11, 13, 19, 0.75);
  backdrop-filter: blur(12px);
  padding: 20px;
}

.changelog-modal {
  width: 100%;
  max-width: 680px;
  max-height: 85vh;
  display: flex;
  flex-direction: column;
  background: linear-gradient(145deg, rgba(26, 32, 48, 0.95), rgba(15, 20, 32, 0.98));
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 16px;
  box-shadow: 0 24px 48px rgba(0, 0, 0, 0.6), 0 0 1px rgba(255, 255, 255, 0.2) inset;
  overflow: hidden;
}

